package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"time"
)

var (
	apiSecret    = os.Getenv("API_SECRET")
	uploadDir    = "/var/app/uploads"
	maxChunkSize uint64 = 10 * 1024 * 1024 // 10MB per chunk
	maxTotalSize uint64 = 100 * 1024 * 1024 // 100MB total
	activeSessions sync.Map
)

type UploadSession struct {
	UserID       string
	FileName     string
	TotalChunks  uint64
	ChunkSize    uint64
	ReceivedSize uint64
	CreatedAt    time.Time
	mu           sync.Mutex
}

type ChunkMetadata struct {
	SessionID  string `json:"session_id"`
	ChunkIndex uint64 `json:"chunk_index"`
	ChunkHash  string `json:"chunk_hash"`
}

func verifyRequestSignature(r *http.Request) bool {
	timestamp := r.Header.Get("X-Timestamp")
	signature := r.Header.Get("X-Signature")
	if timestamp == "" || signature == "" {
		return false
	}

	ts, err := strconv.ParseInt(timestamp, 10, 64)
	if err != nil {
		return false
	}

	// Reject requests whose timestamp deviates more than 5 minutes in
	// either direction (prevents both stale-request and future-dated replay).
	delta := time.Now().Unix() - ts
	if delta < 0 {
		delta = -delta
	}
	if delta > 300 {
		return false
	}

	mac := hmac.New(sha256.New, []byte(apiSecret))
	mac.Write([]byte(fmt.Sprintf("%s:%s:%s", r.Method, r.URL.Path, timestamp)))
	expected := hex.EncodeToString(mac.Sum(nil))

	return subtle.ConstantTimeCompare([]byte(expected), []byte(signature)) == 1
}

func extractUserID(r *http.Request) (string, bool) {
	auth := r.Header.Get("Authorization")
	if !strings.HasPrefix(auth, "Bearer ") {
		return "", false
	}
	token := strings.TrimPrefix(auth, "Bearer ")
	if len(token) != 64 {
		return "", false
	}
	for _, c := range token {
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')) {
			return "", false
		}
	}
	h := sha256.Sum256([]byte(token))
	return hex.EncodeToString(h[:8]), true
}

func sanitizeFilename(name string) (string, bool) {
	name = filepath.Base(name)
	if name == "." || name == ".." || name == "/" {
		return "", false
	}
	if strings.ContainsAny(name, "/\\:\x00") {
		return "", false
	}
	if len(name) > 255 || len(name) == 0 {
		return "", false
	}
	ext := strings.ToLower(filepath.Ext(name))
	allowed := map[string]bool{".pdf": true, ".png": true, ".jpg": true, ".txt": true, ".doc": true}
	if !allowed[ext] {
		return "", false
	}
	return name, true
}

// validateUploadSize checks that the total upload won't exceed limits.
// Uses uint64 arithmetic to prevent overflow in size calculation.
func validateUploadSize(totalChunks uint64, chunkSize uint64) bool {
	// Verify individual chunk size first
	if chunkSize > maxChunkSize {
		return false
	}

	// Verify chunk count is reasonable (prevents overflow even in theory)
	if totalChunks > 10000 {
		return false
	}

	// Calculate expected total size - safe from overflow with uint64
	// and bounded inputs (totalChunks <= 10000, chunkSize <= 10MB)
	expectedTotal := totalChunks * chunkSize

	// Verify total size doesn't exceed maximum
	if expectedTotal > maxTotalSize {
		return false
	}

	return true
}

func handleInitUpload(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	if !verifyRequestSignature(r) {
		http.Error(w, "Unauthorized", 401)
		return
	}

	userID, ok := extractUserID(r)
	if !ok {
		http.Error(w, "Invalid token", 401)
		return
	}

	fileName := r.Header.Get("X-Filename")
	safeName, ok := sanitizeFilename(fileName)
	if !ok {
		http.Error(w, "Invalid filename", 400)
		return
	}

	chunksStr := r.Header.Get("X-Total-Chunks")
	chunkSizeStr := r.Header.Get("X-Chunk-Size")

	chunks, err := strconv.ParseUint(chunksStr, 10, 64)
	if err != nil || chunks == 0 {
		http.Error(w, "Invalid chunk count", 400)
		return
	}

	cSize, err := strconv.ParseUint(chunkSizeStr, 10, 64)
	if err != nil || cSize == 0 {
		http.Error(w, "Invalid chunk size", 400)
		return
	}

	// Validate the upload won't exceed size limits
	if !validateUploadSize(chunks, cSize) {
		http.Error(w, "Upload too large", 413)
		return
	}

	sessionID := generateSessionID(userID, safeName)
	session := &UploadSession{
		UserID:      userID,
		FileName:    safeName,
		TotalChunks: chunks,
		ChunkSize:   cSize,
		CreatedAt:   time.Now(),
	}

	activeSessions.Store(sessionID, session)

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]string{"session_id": sessionID})
}

func handleUploadChunk(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPut {
		http.Error(w, "Method not allowed", 405)
		return
	}

	if !verifyRequestSignature(r) {
		http.Error(w, "Unauthorized", 401)
		return
	}

	userID, ok := extractUserID(r)
	if !ok {
		http.Error(w, "Invalid token", 401)
		return
	}

	var meta ChunkMetadata
	metaHeader := r.Header.Get("X-Chunk-Meta")
	if err := json.Unmarshal([]byte(metaHeader), &meta); err != nil {
		http.Error(w, "Invalid metadata", 400)
		return
	}

	val, ok := activeSessions.Load(meta.SessionID)
	if !ok {
		http.Error(w, "Session not found", 404)
		return
	}

	session := val.(*UploadSession)

	// Verify session belongs to this user
	if session.UserID != userID {
		http.Error(w, "Forbidden", 403)
		return
	}

	// Verify chunk index is valid
	if meta.ChunkIndex >= session.TotalChunks {
		http.Error(w, "Invalid chunk index", 400)
		return
	}

	// Read chunk data - enforce hard limit regardless of session config
	hardLimit := int64(maxChunkSize) + 1
	chunkData, err := io.ReadAll(io.LimitReader(r.Body, hardLimit))
	if err != nil {
		http.Error(w, "Read error", 500)
		return
	}

	if uint64(len(chunkData)) > session.ChunkSize {
		http.Error(w, "Chunk too large", 413)
		return
	}

	// Verify chunk integrity
	hash := sha256.Sum256(chunkData)
	if hex.EncodeToString(hash[:]) != meta.ChunkHash {
		http.Error(w, "Integrity check failed", 400)
		return
	}

	// Write chunk to disk
	userDir := filepath.Join(uploadDir, userID)
	os.MkdirAll(userDir, 0750)

	chunkPath := filepath.Join(userDir, fmt.Sprintf("%s.chunk%d", session.FileName, meta.ChunkIndex))

	// Final path safety check
	absChunk, _ := filepath.Abs(chunkPath)
	absUserDir, _ := filepath.Abs(userDir)
	if !strings.HasPrefix(absChunk, absUserDir+string(os.PathSeparator)) {
		http.Error(w, "Invalid path", 400)
		return
	}

	if err := os.WriteFile(chunkPath, chunkData, 0640); err != nil {
		http.Error(w, "Write error", 500)
		return
	}

	session.mu.Lock()
	session.ReceivedSize += uint64(len(chunkData))
	session.mu.Unlock()

	w.WriteHeader(200)
	w.Write([]byte(`{"status":"ok"}`))
}

func generateSessionID(userID, fileName string) string {
	h := sha256.Sum256([]byte(fmt.Sprintf("%s:%s:%d", userID, fileName, time.Now().UnixNano())))
	return hex.EncodeToString(h[:16])
}

func main() {
	if apiSecret == "" {
		fmt.Fprintf(os.Stderr, "API_SECRET environment variable required\n")
		os.Exit(1)
	}

	http.HandleFunc("/api/upload/init", handleInitUpload)
	http.HandleFunc("/api/upload/chunk", handleUploadChunk)

	server := &http.Server{
		Addr:         "127.0.0.1:8443",
		ReadTimeout:  30 * time.Second,
		WriteTimeout: 30 * time.Second,
		MaxHeaderBytes: 1 << 16,
	}

	fmt.Println("Starting secure upload server on :8443")
	server.ListenAndServe()
}
